/** Cada línea del archivo de 80 bytes pasa a ser una fila con llave natural única. */
@Entity
@Table(name = "directorio_depuracion",
       uniqueConstraints = @UniqueConstraint(columnNames = {"directorio", "pack", "csi"}))
public class DirectorioDepuracion {
    @Id @GeneratedValue Long id;
    @Column(length = 4,  nullable = false) String usuario;     // USER
    @Column(length = 30, nullable = false) String directorio;  // DIR
    @Column(length = 17, nullable = false) String pack;        // PACK
    @Column(length = 2,  nullable = false) String csi;         // CSI 9(02) como texto
    @Column(nullable = false) int dias;                        // DIA 9(02), máximo 4
}

# application.yml  (ya no hace falta el archivo TEMP: la transacción lo sustituye)
